<script setup lang="ts">
import {Mail, RefreshCw, Search, UserCheck, UserX} from 'lucide-vue-next'
const {request}=useApi()
const loading=ref(false),busy=ref(''),notice=ref(''),error=ref(''),find=ref('')
const statusLabels: Record<string,string> = {ACTIVE:'Confirmada',PENDING:'Pendiente',DISABLED:'Desactivada',UNSUBSCRIBED:'Baja solicitada'}
const rows=ref<any[]>([]),total=ref(0),offset=ref(0)
const linking=ref<any>(null),plotOptions=ref<any[]>([]),plotIds=ref<string[]>([])
const filtered=computed(()=>rows.value.filter((r:any)=>[r.email,r.telegram_username,r.status].join(' ').toLowerCase().includes(find.value.toLowerCase())))
async function load(){loading.value=true;error.value='';try{const r:any=await request('/notifications/address-book',{query:{offset:offset.value,limit:100}});rows.value=r.items||[];total.value=r.total||0}catch(e:any){error.value=e?.data?.detail||'No se pudo cargar la libreta.'}finally{loading.value=false}}
async function toggle(row:any){if(!window.confirm(`¿Desea ${row.status==='ACTIVE'?'desactivar':'reactivar'} la suscripción ${row.email}?`))return;busy.value=row.id;notice.value='';error.value='';try{const r:any=await request(`/notifications/address-book/${row.id}`,{method:'PATCH',body:{active:row.status!=='ACTIVE'}});notice.value=r.message;await load()}catch(e:any){error.value=e?.data?.detail||'No se pudo actualizar.'}finally{busy.value=''}}
async function editPlots(row:any){error.value='';try{const r:any=await request('/notifications/address-book/parcel-options');plotOptions.value=r.items||[];plotIds.value=(row.plots||[]).map((p:any)=>p.id);linking.value=row}catch(e:any){error.value=e?.data?.detail||'No se pudieron cargar las parcelas.'}}
async function savePlots(){busy.value=linking.value.id;error.value='';try{const r:any=await request(`/notifications/address-book/${linking.value.id}/parcels`,{method:'PUT',body:{plot_ids:plotIds.value}});linking.value=null;notice.value=r.message;await load()}catch(e:any){error.value=e?.data?.detail||'No se pudo vincular.'}finally{busy.value=''}}
onMounted(load)
</script>
<template><section><p class="notice small">Inscripciones voluntarias, con consentimiento de uso de datos y envío de informaciones. Cada usuario elige sus canales.</p>
<div class="toolbar"><label class="search-input"><Search :size="18"/><input v-model="find" class="input" placeholder="Buscar por correo o Telegram…" aria-label="Buscar suscriptores"></label><div class="row"><NuxtLink to="/fecoclima-ia/suscripciones" class="btn btn-primary" target="_blank">Abrir inscripción pública</NuxtLink><button class="btn btn-light" :disabled="loading" @click="load"><RefreshCw :size="17"/> Actualizar</button></div></div>
<p v-if="notice" class="notice" role="status">{{notice}}</p><p v-if="error" class="notice notice-danger" role="alert">{{error}}</p>
<article class="card"><div class="table-wrap"><table><thead><tr><th>Correo</th><th>Parcelas vinculadas</th><th>Telegram</th><th>Canales autorizados</th><th>Consentimiento</th><th>Estado</th><th>Fecha</th><th>Acción</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td><Mail :size="15" class="inline-icon"/> {{row.email}}</td><td><span v-for="plot in row.plots||[]" :key="plot.id" class="linked-plot">{{plot.name}}<small class="muted coverage-note">{{plot.stations?.length?plot.stations.map((s:any)=>s.name+' ('+s.coverage_pct+' %)').join(', '):'Sin cobertura actual'}}</small></span><span v-if="!row.plots?.length" class="small muted">Sin parcelas · no recibe alertas</span></td><td>{{row.telegram_username?'@'+row.telegram_username:'—'}}<small class="muted">{{row.telegram_enabled?(row.telegram_active?' · Vinculado':' · Pendiente de vincular'):''}}</small></td><td>{{[row.email_enabled?'Correo':'',row.telegram_enabled?'Telegram':''].filter(Boolean).join(' · ')||'Ninguno'}}</td><td>{{row.consent_at?new Date(row.consent_at).toLocaleDateString('es-CR'):'Anterior'}}<small class="muted"> {{row.consent_version}}</small></td><td><span class="badge" :class="row.status==='ACTIVE'?'badge-success':row.status==='PENDING'?'badge-warning':'badge-danger'">{{ statusLabels[row.status] ||row.status}}</span></td><td>{{row.confirmed_at?new Date(row.confirmed_at).toLocaleDateString('es-PY'):'—'}}</td><td><button v-if="row.status==='ACTIVE'||row.status==='DISABLED'" class="btn btn-light" :disabled="!!busy" @click="editPlots(row)">Vincular parcelas</button><button v-if="row.status==='ACTIVE'||row.status==='DISABLED'" class="btn btn-light" :disabled="busy===row.id" @click="toggle(row)"><UserX v-if="row.status==='ACTIVE'" :size="17"/><UserCheck v-else :size="17"/>{{row.status==='ACTIVE'?'Desactivar':'Reactivar'}}</button><span v-else class="small muted">{{row.status==='PENDING'?'Esperando confirmación':'Requiere nuevo consentimiento'}}</span></td></tr><tr v-if="!filtered.length"><td colspan="8">{{loading?'Cargando…':'No hay suscripciones para mostrar.'}}</td></tr></tbody></table></div></article>
<div class="row pagination"><span class="small muted">{{total}} registros</span><button class="btn btn-light" :disabled="offset===0||loading" @click="offset=Math.max(0,offset-100);load()">Anterior</button><button class="btn btn-light" :disabled="offset+100>=total||loading" @click="offset+=100;load()">Siguiente</button></div>
<p class="notice small">Por seguridad, no se puede activar sin consentimiento una dirección pendiente o dada de baja. Un usuario puede volver a suscribirse desde la página pública.</p><div v-if="linking" class="link-overlay" @click.self="linking=null"><form class="card card-body link-dialog" role="dialog" aria-modal="true" aria-labelledby="link-title" @submit.prevent="savePlots"><h3 id="link-title">Parcelas de {{linking.email}}</h3><p>Recibirá avisos únicamente de estaciones que cubran estas parcelas, por sus canales autorizados.</p><label v-for="plot in plotOptions" :key="plot.id" class="plot-choice"><input v-model="plotIds" type="checkbox" :value="plot.id">{{plot.name}}</label><p v-if="!plotOptions.length">No hay parcelas activas.</p><div class="row"><button class="btn btn-light" type="button" @click="linking=null">Cancelar</button><button class="btn btn-primary" :disabled="!!busy">Guardar vínculos</button></div></form></div></section></template>
<style scoped>.search-input{display:flex;align-items:center;position:relative;max-width:420px;width:100%}.search-input svg{position:absolute;left:12px;color:var(--fc-secondary)}.search-input input{padding-left:40px}.inline-icon{vertical-align:middle}.pagination{margin:18px 0}.row{flex-wrap:wrap}</style>

<style scoped>.linked-plot{display:block;margin:4px 0}.link-overlay{position:fixed;inset:0;background:#001e3780;z-index:100;display:grid;place-items:center;padding:20px}.link-dialog{width:min(560px,100%);max-height:85vh;overflow:auto;display:grid;gap:16px}.plot-choice{display:flex;align-items:center;gap:10px}.plot-choice input{width:18px;height:18px}</style>

<style scoped>.coverage-note{display:block;margin-top:3px}</style>
